private boolean unlink(ListNodeImpl<E> node){
    if (node == null) {
        return false;
    }

    ListNodeImpl<E> prev = node.getPrevious();
    ListNodeImpl<E> next = node.getNext();

    if (prev == null) {
        first = next;
    } else {
        prev.setNext(next);
        node.setPrevious(null);
    }

    if (next == null) {
        last = prev;
    } else {
        next.setPrevious(prev);
        node.setNext(null);
    }

    size--;
    node = null;
    return true;
}

