    }

    int leftPartitionSize;
    int rightPartitionSize;

    try {
        leftPartitionSize = Integer.parseInt(resultMap.getOrDefault("leftPartitionSize", "0").toString());
        rightPartitionSize = Integer.parseInt(resultMap.getOrDefault("rightPartitionSize", "0").toString());
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("Partition sizes must be valid integers", e);
    }

    if (leftPartitionSize <= 0 || rightPartitionSize <= 0) {
        throw new IllegalArgumentException("Partition sizes must be greater than zero");
    }

    List<V> leftPartition = new ArrayList<>();
    List<V> rightPartition = new ArrayList<>();

    for (int i = 0; i < leftPartitionSize; i++) {
        V vertex = target.addVertex();
        leftPartition.add(vertex);
    }

    for (int i = 0; i < rightPartitionSize; i++) {
        V vertex = target.addVertex();
        rightPartition.add(vertex);
    }

    for (V leftVertex : leftPartition) {
        for (V rightVertex : rightPartition) {
            target.addEdge(leftVertex, rightVertex);
        }
    }
}

