String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    // Normalize the path by removing any trailing slash
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }

    // Split the path into segments
    String[] pathSegments = path.split("/");
    String[] relativeSegments = relativePath.split("/");

    for (String segment : relativeSegments) {
        if (segment.equals("..")) {
            // Move up one directory, but don't go past the root
            if (pathSegments.length > 0) {
                pathSegments = Arrays.copyOf(pathSegments, pathSegments.length - 1);
            }
        } else if (!segment.equals(".")) {
            // Add the segment to the path
            String[] newPathSegments = new String[pathSegments.length + 1];
            System.arraycopy(pathSegments, 0, newPathSegments, 0, pathSegments.length);
            newPathSegments[pathSegments.length] = segment;
            pathSegments = newPathSegments;
        }
    }

    // Join the segments back into a path
    return String.join("/", pathSegments);
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path must not be null");
    }

    // Normalize the path and remove trailing slash if present
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }

    // Split paths into components
    String[] pathComponents = path.split("/");
    String[] relativeComponents = relativePath.split("/");

    int pathIndex = pathComponents.length - 1;

    // Process each component in the relative path
    for (String component : relativeComponents) {
        if (component.equals("..")) {
            if (pathIndex >= 0) {
                pathIndex--;
            }
        } else if (!component.equals(".")) {
            pathComponents = java.util.Arrays.copyOf(pathComponents, pathIndex + 2);
            pathComponents[++pathIndex] = component;
        }
    }

    // Build the resulting path
    StringBuilder resultPath = new StringBuilder();
    for (int i = 0; i <= pathIndex; i++) {
        if (i > 0) {
            resultPath.append("/");
        }
        resultPath.append(pathComponents[i]);
    }

    return resultPath.toString();
}

