private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    try {
        if (descriptor.charAt(0) == '(') { // Method descriptor
            int index = 1;
            while (descriptor.charAt(index) != ')') {
                index = consumeType(descriptor, index);
            }
        } else { // Field descriptor
            consumeType(descriptor, 0);
        }
    } catch (StringIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor format", e);
    }
}

private int consumeType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'B': case 'C': case 'D': case 'F': case 'I': case 'J': case 'S': case 'Z':
            index++; // Primitive types
            break;
        case 'L':
            index = descriptor.indexOf(';', index) + 1; // Object type
            if (index == 0) {
                throw new IllegalArgumentException("Invalid object type in descriptor");
            }
            break;
        case '[':
            index = consumeType(descriptor, index + 1); // Array type
            break;
        default:
            throw new IllegalArgumentException("Invalid type character in descriptor: " + descriptor.charAt(index));
    }
    return index;
}

void function ( final String descriptor ) {
    if ( descriptor == null || descriptor.isEmpty() ) {
        throw new IllegalArgumentException( "Descriptor cannot be null or empty" );
    }

    if ( descriptor.charAt( 0 ) == '(' ) { // Method descriptor
        int i = 1;
        while ( descriptor.charAt( i ) != ')' ) {
            i = popTypeFromDescriptor( descriptor, i );
        }
    } else {
        popTypeFromDescriptor( descriptor, 0 );
    }
}

private int popTypeFromDescriptor( final String descriptor, int index ) {
    switch ( descriptor.charAt( index ) ) {
        case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z': // Base types
            index++;
            break;
        case 'J': case 'D': // Long and Double take two stack slots
            index++;
            break;
        case 'L': // Object types
            index = descriptor.indexOf( ';', index ) + 1;
            if ( index == 0 ) {
                throw new IllegalArgumentException( "Invalid object type descriptor" );
            }
            break;
        case '[': // Array types
            while ( descriptor.charAt( index ) == '[' ) {
                index++;
            }
            if ( descriptor.charAt( index ) == 'L' ) {
                index = descriptor.indexOf( ';', index ) + 1;
                if ( index == 0 ) {
                    throw new IllegalArgumentException( "Invalid array type descriptor" );
                }
            } else {
                index++;
            }
            break;
        default:
            throw new IllegalArgumentException( "Invalid descriptor character: " + descriptor.charAt( index ) );
    }
    return index;
}

void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor, extract argument types
        int index = 1; // skip '('
        while (descriptor.charAt(index) != ')') {
            index = popType(descriptor, index);
        }
    } else {
        // It's a field descriptor, pop a single type
        popType(descriptor, 0);
    }
}

private int popType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'B':
        case 'C':
        case 'D':
        case 'F':
        case 'I':
        case 'S':
        case 'Z':
        case 'L': // Objects are treated as a single slot
            // These types take up one slot in the stack
            // pop one element from the stack
            if (outputFrameStack.isEmpty()) {
                throw new IllegalStateException("Output frame stack is empty");
            }
            outputFrameStack.pop();
            return index + 1;
        case 'J':
        case 'D':
            // These types take up two slots in the stack
            // pop two elements from the stack
            if (outputFrameStack.size() < 2) {
                throw new IllegalStateException("Not enough elements in the output frame stack");
            }
            outputFrameStack.pop();
            outputFrameStack.pop();
            return index + 1;
        case '[':
            // Arrays are treated as a single slot
            // pop one element from the stack
            if (outputFrameStack.isEmpty()) {
                throw new IllegalStateException("Output frame stack is empty");
            }
            outputFrameStack.pop();
            return consumeArrayDescriptor(descriptor, index + 1);
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
