private int consumeArrayDescriptor(final String descriptor, int index) {
    while (descriptor.charAt(index) == '[') {
        index++;
    }
    if (descriptor.charAt(index) == 'L') {
        // Object type, skip over the class name
        index = descriptor.indexOf(';', index) + 1;
    }
    return index;
}

